-- demo rows: a landlord, two buildings with eight units, seven tenants, three
-- months of rent and a maintenance queue with photos. Every date is relative to
-- the day the seed runs, so the rent roll always reads like a normal month.

insert into users (email, name, role, passwordHash) values
  ('dana@leaseleaf.test',   'Dana Whitaker', 'landlord', crypt('leaseleaf', genSalt('bf', 12))),
  ('priya@leaseleaf.test',  'Priya Shah',    'tenant',   crypt('leaseleaf', genSalt('bf', 12))),
  ('marcus@leaseleaf.test', 'Marcus Bell',   'tenant',   crypt('leaseleaf', genSalt('bf', 12))),
  ('elena@leaseleaf.test',  'Elena Ruiz',    'tenant',   crypt('leaseleaf', genSalt('bf', 12))),
  ('tom@leaseleaf.test',    'Tom Okafor',    'tenant',   crypt('leaseleaf', genSalt('bf', 12))),
  ('hannah@leaseleaf.test', 'Hannah Lee',    'tenant',   crypt('leaseleaf', genSalt('bf', 12))),
  ('sam@leaseleaf.test',    'Sam Novak',     'tenant',   crypt('leaseleaf', genSalt('bf', 12))),
  ('grace@leaseleaf.test',  'Grace Kim',     'tenant',   crypt('leaseleaf', genSalt('bf', 12)));

insert into buildings (name, address) values
  ('Alder Court', '214 Alder Street'),
  ('Birch House', '88 Birch Avenue');

insert into units (buildingId, label, bedrooms, bathrooms)
select b.id, u.label, u.bedrooms, u.bathrooms
  from (values
    ('Alder Court', '1A', 2, 1.0),
    ('Alder Court', '1B', 1, 1.0),
    ('Alder Court', '2A', 2, 1.5),
    ('Alder Court', '2B', 1, 1.0),
    ('Birch House', '101', 1, 1.0),
    ('Birch House', '102', 1, 1.0),
    ('Birch House', '201', 2, 1.0),
    ('Birch House', '202', 3, 2.0)
  ) as u (building, label, bedrooms, bathrooms)
  join buildings b on b.name = u.building;

insert into leases (unitId, tenantId, status, rentCents, dueDay, startDate)
select un.id, us.id, 'active', l.rentCents, l.dueDay,
       (date_trunc('month', current_date) - make_interval(months => l.monthsAgo))::date
  from (values
    ('priya@leaseleaf.test',  'Alder Court', '1A',  165000, 1,  14),
    ('marcus@leaseleaf.test', 'Alder Court', '1B',  142500, 1,  26),
    ('elena@leaseleaf.test',  'Alder Court', '2A',  170000, 1,  8),
    ('tom@leaseleaf.test',    'Alder Court', '2B',  147500, 5,  19),
    ('hannah@leaseleaf.test', 'Birch House', '101', 135000, 1,  5),
    ('sam@leaseleaf.test',    'Birch House', '102', 139500, 1,  31),
    ('grace@leaseleaf.test',  'Birch House', '201', 155000, 15, 11)
  ) as l (email, building, unit, rentCents, dueDay, monthsAgo)
  join users us on us.email = l.email
  join buildings b on b.name = l.building
  join units un on un.buildingId = b.id and un.label = l.unit;

-- two months back, last month, this month and next month's charge
insert into rentCharges (leaseId, month, dueDate, amountCents)
select l.id,
       to_char(m.start, 'YYYY-MM'),
       (m.start + make_interval(days => l.dueDay - 1))::date,
       l.rentCents
  from leases l
 cross join lateral (
   select (date_trunc('month', current_date) + make_interval(months => n))::date as start
     from generate_series(-2, 1) as n
 ) m;

-- everything before this month was paid, most of it a day or two early; Tom
-- was four days late last month
update rentCharges c
   set status = 'paid',
       method = 'card',
       paidAt = c.dueDate - make_interval(days => (abs(hashtext(c.id::text)) % 3)) + time '10:24',
       reminderSentAt = c.dueDate - 3 + time '09:00'
 where c.month < to_char(current_date, 'YYYY-MM');

update rentCharges c
   set paidAt = c.dueDate + 4 + time '18:02',
       lateNoticeSentAt = c.dueDate + 1 + time '09:00'
  from leases l
  join users u on u.id = l.tenantId
 where l.id = c.leaseId
   and u.email = 'tom@leaseleaf.test'
   and c.month = to_char(current_date - interval '1 month', 'YYYY-MM');

-- this month: five paid, Tom and Sam still owe
update rentCharges c
   set status = 'paid',
       method = 'card',
       paidAt = least(c.dueDate - 1, current_date) + time '08:41',
       reminderSentAt = c.dueDate - 3 + time '09:00'
  from leases l
  join users u on u.id = l.tenantId
 where l.id = c.leaseId
   and c.month = to_char(current_date, 'YYYY-MM')
   and u.email not in ('tom@leaseleaf.test', 'sam@leaseleaf.test')
   and c.dueDate - 1 <= current_date;

update rentCharges c
   set reminderSentAt = c.dueDate - 3 + time '09:00',
       lateNoticeSentAt = case when c.dueDate < current_date then c.dueDate + 1 + time '09:00' end
 where c.month = to_char(current_date, 'YYYY-MM')
   and c.status = 'open'
   and c.dueDate - 3 <= current_date;

-- Marcus paid next month early
update rentCharges c
   set status = 'paid',
       method = 'card',
       paidAt = current_date - 1 + time '20:15'
  from leases l
  join users u on u.id = l.tenantId
 where l.id = c.leaseId
   and u.email = 'marcus@leaseleaf.test'
   and c.month = to_char(current_date + interval '1 month', 'YYYY-MM');

-- when next month's rent is a day or two away, a few tenants have already paid it
update rentCharges c
   set status = 'paid',
       method = 'card',
       paidAt = greatest(current_date - (abs(hashtext(c.id::text)) % 2), c.dueDate - 3) + time '07:52'
  from leases l
  join users u on u.id = l.tenantId
 where l.id = c.leaseId
   and u.email in ('priya@leaseleaf.test', 'elena@leaseleaf.test', 'hannah@leaseleaf.test')
   and c.month = to_char(current_date + interval '1 month', 'YYYY-MM')
   and c.dueDate - current_date <= 2;

insert into maintenanceRequests (unitId, tenantId, title, description, urgency, status, scheduledFor, completedAt, createdAt)
select l.unitId, u.id, r.title, r.description, r.urgency::requestUrgency, r.status::requestStatus,
       current_date + r.scheduledIn,
       case when r.status = 'done' then now() - interval '6 days' end,
       now() - r.age
  from (values
    ('priya@leaseleaf.test', 'Kitchen faucet keeps dripping',
     'The kitchen faucet drips about once a second even when the handle is all the way off. It started last week and is getting worse. It keeps me up at night.',
     'normal', 'new', null::integer, interval '2 days'),
    ('hannah@leaseleaf.test', 'Radiator not heating the bedroom',
     'The bedroom radiator stays cold. The living room one works. The thermostat is set to 68 and the bedroom is at 58 this morning.',
     'urgent', 'scheduled', 1, interval '3 days'),
    ('sam@leaseleaf.test', 'Cracked pane in the living room window',
     'Something hit the upper left pane of the living room window and it cracked in a star pattern. It is not letting air in yet, but it looks like it could break.',
     'normal', 'scheduled', 4, interval '4 days'),
    ('tom@leaseleaf.test', 'Bathroom fan rattles loudly',
     'The bathroom exhaust fan makes a loud rattling noise when it runs, like something is loose inside.',
     'low', 'done', null::integer, interval '12 days'),
    ('elena@leaseleaf.test', 'Hallway light flickers',
     'The ceiling light in the hallway flickers for a minute or so after I turn it on. I changed the bulb and it still does it.',
     'low', 'new', null::integer, interval '5 hours')
  ) as r (email, title, description, urgency, status, scheduledIn, age)
  join users u on u.email = r.email
  join leases l on l.tenantId = u.id;

insert into maintenanceComments (requestId, authorId, authorName, authorRole, body, createdAt)
select m.id, u.id, u.name, u.role, c.body, now() - c.age
  from (values
    ('Radiator not heating the bedroom', 'dana@leaseleaf.test',
     'Sorry about this. I have Northside Heating booked for tomorrow between 9 and 11am. They will bleed the radiator and check the valve.', interval '2 days 20 hours'),
    ('Radiator not heating the bedroom', 'hannah@leaseleaf.test',
     'Thank you! I will leave the bedroom door open for them.', interval '2 days 18 hours'),
    ('Cracked pane in the living room window', 'dana@leaseleaf.test',
     'Thanks for the photo. The glass is on order and the glazier will come as soon as it arrives. Please keep the blinds down on that side until then.', interval '3 days 22 hours'),
    ('Bathroom fan rattles loudly', 'dana@leaseleaf.test',
     'I replaced the fan motor this morning. Let me know if it is still noisy.', interval '6 days'),
    ('Bathroom fan rattles loudly', 'tom@leaseleaf.test',
     'Quiet as can be now. Thanks, Dana!', interval '5 days 20 hours')
  ) as c (title, email, body, age)
  join maintenanceRequests m on m.title = c.title
  join users u on u.email = c.email;

insert into maintenancePhotos (requestId, name, contentType, data)
select m.id, p.name, 'image/jpeg', decode(p.data, 'base64')
  from (values
    ('Kitchen faucet keeps dripping', 'faucet.jpg', ''),
    ('Radiator not heating the bedroom', 'radiator.jpg', ''),
    ('Cracked pane in the living room window', 'window.jpg', ''),
    ('Bathroom fan rattles loudly', 'fan.jpg', '')
  ) as p (title, name, data)
  join maintenanceRequests m on m.title = p.title;
